const root = $input.first().json;
const workflows = Array.isArray(root.data) ? root.data : (Array.isArray(root) ? root : []);
const input = $('Read-Only Inspection Input').first().json || {};
const includeInactive = input.include_inactive !== false;
const projectTag = String(input.project_tag || '').trim().toLowerCase();

const safeCredentialRefs = (credentials) => {
  if (!credentials || typeof credentials !== 'object') return [];
  return Object.entries(credentials).map(([type, ref]) => ({
    type,
    reference_name: ref && typeof ref === 'object' && typeof ref.name === 'string' ? ref.name : null
  }));
};

const category = (type) => {
  const t = String(type || '').toLowerCase();
  if (t.includes('trigger') || t.includes('webhook')) return 'trigger';
  if (t.includes('executeworkflow')) return 'sub_workflow';
  if (/openai|anthropic|gemini|ollama|langchain/.test(t)) return 'ai_provider';
  if (/slack|line|telegram|gmail|email|outlook/.test(t)) return 'channel';
  if (/postgres|supabase|mysql|redis|googleSheets|drive|s3|r2/i.test(type || '')) return 'storage';
  if (t.includes('httprequest')) return 'external_api';
  return 'processing';
};

const inventory = [];
for (const wf of workflows) {
  if (!wf || typeof wf !== 'object') continue;
  if (!includeInactive && !wf.active) continue;
  const tags = Array.isArray(wf.tags) ? wf.tags.map(t => String(t.name || t).toLowerCase()) : [];
  if (projectTag && !tags.some(t => t.includes(projectTag))) continue;

  const nodes = Array.isArray(wf.nodes) ? wf.nodes : [];
  const safeNodes = nodes.map(n => ({
    name: String(n.name || ''),
    type: String(n.type || ''),
    type_version: n.typeVersion ?? null,
    disabled: n.disabled === true,
    category: category(n.type),
    credential_references: safeCredentialRefs(n.credentials),
    has_webhook: Boolean(n.webhookId || String(n.type || '').toLowerCase().includes('webhook'))
  }));

  const edges = [];
  const connections = wf.connections && typeof wf.connections === 'object' ? wf.connections : {};
  for (const [from, outputs] of Object.entries(connections)) {
    if (!outputs || typeof outputs !== 'object') continue;
    for (const groups of Object.values(outputs)) {
      if (!Array.isArray(groups)) continue;
      groups.forEach((group, outputIndex) => {
        if (!Array.isArray(group)) return;
        group.forEach(edge => edges.push({
          from,
          to: String(edge.node || ''),
          output_index: outputIndex,
          input_type: String(edge.type || 'main')
        }));
      });
    }
  }

  inventory.push({
    workflow_id: String(wf.id || ''),
    workflow_name: String(wf.name || ''),
    active: wf.active === true,
    archived: wf.isArchived === true,
    tags: tags,
    node_count: safeNodes.length,
    nodes: safeNodes,
    connections: edges
  });
}

const names = new Map();
for (const wf of inventory) {
  const key = wf.workflow_name.toLowerCase();
  if (!names.has(key)) names.set(key, []);
  names.get(key).push(wf.workflow_id);
}
const duplicateWorkflowNames = [...names.entries()]
  .filter(([, ids]) => ids.length > 1)
  .map(([name, ids]) => ({ name, workflow_ids: ids }));

return [{
  json: {
    ok: true,
    mode: 'READ_ONLY',
    generated_at: new Date().toISOString(),
    workflow_count: inventory.length,
    inventory,
    dependency_edges: inventory.flatMap(w => w.connections.map(e => ({ workflow_id: w.workflow_id, ...e }))),
    credential_reference_policy: 'name_and_type_only_no_values',
    risks: { duplicate_workflow_names: duplicateWorkflowNames },
    prohibited_data_confirmed_absent: [
      'credential_values','api_keys','tokens','node_parameters','webhook_paths','execution_payloads','customer_data'
    ]
  }
}];
